import { test, expect } from '@playwright/test';

test.describe('ARIA Landmarks for Page Regions', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/landmarks-demo');
  });

  test('should correctly apply ARIA landmarks to page regions', async ({ page }) => {
    // Verify main content region has role="main"
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(mainContent).toHaveAttribute('aria-label', 'Main content area');

    // Verify navigation region has role="navigation"
    const navRegion = page.getByRole('navigation');
    await expect(navRegion).toBeVisible();
    await expect(navRegion).toHaveAttribute('aria-label', 'Navigation');

    // Verify search region has role="search"
    const searchRegion = page.getByRole('search');
    await expect(searchRegion).toBeVisible();
    await expect(searchRegion).toHaveAttribute('aria-label', 'Search');

    // Verify footer region has role="contentinfo"
    const footerRegion = page.getByRole('contentinfo');
    await expect(footerRegion).toBeVisible();
    await expect(footerRegion).toHaveAttribute('aria-label', 'Footer');

    // Verify page has role="document"
    const pageRegion = page.getByRole('document');
    await expect(pageRegion).toBeVisible();
    await expect(pageRegion).toHaveAttribute('aria-label', 'Document');

    // Verify page has role="banner"
    const bannerRegion = page.getByRole('banner');
    await expect(bannerRegion).toBeVisible();
    await expect(bannerRegion).toHaveAttribute('aria-label', 'Banner');
  });

  test('should handle dynamic content updates with correct ARIA landmarks', async ({ page }) => {
    // Initial verification
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(mainContent).toHaveAttribute('aria-label', 'Main content area');

    // Navigate to a different page
    const navLink = page.getByRole('link', { name: /contact/i });
    await navLink.click();
    await expect(page).toHaveURL(/contact/);

    // Verify navigation region still has correct role and label
    const navRegion = page.getByRole('navigation');
    await expect(navRegion).toBeVisible();
    await expect(navRegion).toHaveAttribute('aria-label', 'Navigation');

    // Verify main content region has updated content
    const mainContent = page.getByRole('main');
    await expect(mainContent).toBeVisible();
    await expect(mainContent).toHaveText(/contact information/i);

    // Verify footer region still has correct role and label
    const footerRegion = page.getByRole('contentinfo');
    await expect(footerRegion).toBeVisible();
    await expect(footerRegion).toHaveAttribute('aria-label', 'Footer');

    // Verify page has correct role and label
    const pageRegion = page.getByRole('document');
    await expect(pageRegion).toBeVisible();
    await expect(pageRegion).toHaveAttribute('aria-label', 'Document');
  });
});
